message.content:
{
  "description": "The creature is a quadrupedal hybrid that is mostly a brown bear in overall shape and covering, with glossy beetle parts integrated into its body. It stands in right-facing profile on four thick furry legs, covered in dense shaggy brown fur that is lighter tan on the muzzle and darker on the lower legs. The head, ears, torso, legs and paws are bear-like, while the back, neck, sides and rear bear shiny dark reddish-brown beetle elytra, translucent veined membranous wings protruding from the shoulder and chest, rows of narrow slit-like openings in the fur on the flank and hip, and a long segmented armored tail ending in two small points.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with dense brown fur, lighter tan fur on the muzzle, a large dark brown-black nose, small round brown eyes, and a slightly open mouth showing the lower lip",
      "where": "at the front top of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears covered in thick brown fur with slightly darker edges",
      "where": "on top of the head, one behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in long shaggy dark brown fur, forelegs under the chest and hind legs under the hips",
      "where": "supporting the body from below, two front and two rear"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with visible long curved light tan claws and dark pads, fur covering the top of the paw",
      "where": "at the ends of the four legs on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long segmented glossy dark reddish-brown tail resembling a beetle abdomen, made of overlapping hard plates with a small two-pronged fork at the tip",
      "where": "extending down and slightly outward from the rear of the body"
    },
    {
      "part": "wings",
      "looks_like": "translucent membranous wings with dark brown branching veins and a light amber-tan tint, thin and slightly crinkled, attached at the base to glossy elytra",
      "where": "one assembly with two overlapping membranes extending outward from the right flank/shoulder, and one single membrane extending outward from the left chest"
    },
    {
      "part": "shell",
      "looks_like": "glossy smooth hard dark reddish-brown beetle elytra with a distinct central suture line and reflective highlights, oval and convex",
      "where": "embedded in the fur on the back of the neck (two small), on the side of the neck (two small), and a large one on the mid-side/shoulder"
    },
    {
      "part": "plates",
      "looks_like": "hard shiny overlapping dark reddish-brown plates with visible segment lines",
      "where": "forming the segments of the tail and the surfaces of the elytra on the neck and side"
    },
    {
      "part": "gills",
      "looks_like": "rows of narrow vertical slit-like openings with dark interiors, resembling gills or insect spiracles, surrounded by fur",
      "where": "a row of about five slits on the mid-flank in the fur, and a diagonal row of about eight slits on the hip"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 3,
  "extra_limb_pieces": 0,
  "tails": 1
}
